2	/**
3	 * resolve_entry_agent.ts — Parse the "/agent-name" slash command from a
4	 * newly-opened issue's body, and emit agent/number/type/notify as step
5	 * outputs for atomaton-entry.wac.ts.
6	 *
7	 * Env: NUMBER, SENDER (issue number + the user who opened it), GITHUB_EVENT_PATH
8	 * Writes to $GITHUB_OUTPUT: agent, number, type, notify -- only if a valid
9	 * slash command was found; otherwise writes nothing, so a downstream
10	 * `if: steps.resolve.outputs.agent != ''` naturally stays false.
11	 *
12	 * The command may sit anywhere in the body on a line of its own -- an issue
13	 * that argues its case and closes with `/atomaton` dispatches (#488, #489
14	 * each closed with one and started nothing). What keeps the scan from
15	 * mistaking prose for a dispatch is that the WHOLE line must be the command:
16	 * an agent mentioned inside a sentence never matches.
17	 */
18	import { readFileSync, appendFileSync } from "node:fs";
19	import { isAgentName, AGENT_NAME_PATTERN } from "../../domain/work/agent-name.ts";
20	import { proseOnly } from "../../adapters/github/tags.ts";
21	import { defineScript } from "./lib/script-ref.ts";
22	
23	export const ref = defineScript(import.meta.url);
24	
25	interface GithubIssueOpenedEvent {
26	  issue?: { body?: string };
27	}
28	
29	/**
30	 * The prose lines a command may sit on, in order.
31	 *
32	 * Blank lines and HTML comments are skipped because neither is visible on the
33	 * rendered issue: an issue that carries only an `atomaton:notify` tag before
34	 * its command looks exactly right to a person. Atomaton writes such comments
35	 * itself — the `atomaton:notify` tag `create_sub_issue` prefixes a body with
36	 * is one — and an issue that carried one silently started nothing.
37	 *
38	 * A command may also sit below the prose, on a line of its own (#488, #489).
39	 * What keeps reading past the opening paragraph from turning a discussion's
40	 * mention of `/engineer` into a dispatch is that the WHOLE line has to be the
41	 * command: an agent named inside a sentence never matches.
42	 *
43	 * Fenced code is skipped too (#311), for the opposite reason: it is perfectly visible.
44	 * A `/engineer` inside a code block is somebody quoting the format, not making a
45	 * request, and the thread readers do not take it for one. `proseOnly` blanks the
46	 * fences, so these lines are the body's prose, and the entry and the thread
47	 * answer "is this a command" the same way about the same body.
48	 */
49	function proseLines(body: string): string[] {
50	  const lines: string[] = [];
51	  for (const raw of body.split("\n")) {
52	    const line = raw.trim();
53	    if (!line) continue;
54	    if (line.startsWith("<!--") && line.endsWith("-->")) continue;
55	    lines.push(line);
56	  }
57	  return lines;
58	}
59	
60	/** A line that is exactly one slash command and nothing else: `/engineer`. */
61	const BARE_COMMAND = new RegExp(`^/(${AGENT_NAME_PATTERN})$`);
62	
63	function bareCommand(line: string): string | undefined {
64	  const m = BARE_COMMAND.exec(line);
65	  return m?.[1];
66	}
