68	function main(): void {
69	  const eventPath = process.env.GITHUB_EVENT_PATH;
70	  const number = process.env.NUMBER ?? "";
71	  const sender = process.env.SENDER ?? "";
72	  const githubOutput = process.env.GITHUB_OUTPUT;
73	
74	  if (!eventPath) {
75	    console.error("resolve_entry_agent: GITHUB_EVENT_PATH is not set");
76	    return;
77	  }
78	
79	  const event = JSON.parse(readFileSync(eventPath, "utf8")) as GithubIssueOpenedEvent;
80	  const body = proseOnly(event.issue?.body ?? "");
81	  const lines = proseLines(body);
82	
83	  /** The one place agent + number + type + notify are written from. */
84	  const emit = (agent: string): void => {
85	    if (githubOutput) {
86	      appendFileSync(
87	        githubOutput,
88	        [`agent=${agent}`, `number=${number}`, "type=issue", `notify=${sender}`].join("\n") + "\n",
89	      );
90	    }
91	  };
92	
93	  // The opening line keeps the strict reading it always had: a slash there that
94	  // is not a bare name is the typo / instructions-on-the-line case, worth a
95	  // warning rather than a scan. The name is spliced into shell text downstream
96	  // (`AGENT="${{ inputs.agent }}"` in atomaton-runner) and into an
97	  // agent-definition path, so anything that is not a bare name stops before
98	  // anything reaches that text. Emitting no output leaves the caller's
99	  // `if: steps.resolve.outputs.agent != ''` false, which is the same no-op as an
100	  // issue that opened with no slash command at all.
101	  //
102	  // A warning rather than silence because the two realistic causes are a typo
103	  // and the documented-elsewhere habit of writing instructions on the command
104	  // line: `/engineer implement X` reads as valid to a human and is not.
105	  const first = lines[0] ?? "";
106	  if (first.startsWith("/")) {
107	    const agent = first.slice(1).trim();
108	    if (agent && !isAgentName(agent)) {
109	      console.error(
110	        `::warning::Ignoring '/${agent}': an agent command must be a bare name on its own line ` +
111	          `(for example '/engineer'), with any instructions on the lines after it.`,
112	      );
113	    } else if (agent) {
114	      emit(agent);
115	      return;
116	    }
117	    // A first line that is merely "/" writes nothing and falls through.
118	  }
119	
120	  // Everywhere else, an entire line that is exactly one bare command counts --
121	  // the issue that argues its case first and calls at the end. Sentences that
122	  // mention an agent, and slash-leading paths like `/tmp/x`, are whole prose
123	  // lines that are not commands, and never match. The scan runs even after a
124	  // warned opening line: the warning is about that line, not a veto on the body.
125	  for (const line of lines.slice(1)) {
126	    const agent = bareCommand(line);
127	    if (agent !== undefined) {
128	      emit(agent);
129	      return;
130	    }
131	  }
132	}
