10	import { ghRead } from "../../../adapters/github/gh.ts";
11	
12	/**
13	 * The marker that makes the notice findable, and that keeps it to one.
14	 *
15	 * A comment rather than a label: labels are the project's to name and this is not,
16	 * and searching for a comment body needs no label to exist first.
17	 */
18	export const NOTICE_MARKER = "<!-- atomaton:new-release -->";
19	
20	/**
21	 * The open notice's number, `0` for none, or null when the list could not be read.
22	 *
23	 * ## Why the marker is checked here rather than searched for
24	 *
25	 * The query is the title's own words, and the marker is then checked in the body in
26	 * TypeScript. Title words are certainly indexed; a hidden HTML comment is not
27	 * something this can be sure of from here, and a query the index does not match
28	 * would leave a run opening a fresh notice every day — the one failure that
29	 * compounds. Checking the body makes the other direction safe too: an issue whose
30	 * title happens to match, and which no run of this wrote, is not edited.
31	 *
32	 * ## Why the state is filtered here too
33	 *
34	 * `--state open` is passed, and the answer is held to it again below. Whether `gh`
35	 * applies a state filter when `--search` is alongside it is not something this
36	 * repository can measure — the fake `gh` matches argv and has no search API — and
37	 * getting it wrong is expensive in one direction: a CLOSED notice read as open would
38	 * be edited every day instead of a new one being opened after the owner closed it.
39	 * So the request asks for `state` and the answer is filtered on it, which is correct
40	 * whichever way the flag behaves.
41	 */
42	export function findOpenNotice(repo: string): number | null {
43	  const result = ghRead(
44	    "issue", "list", "--repo", repo, "--state", "open",
45	    "--search", `"Atomaton release" in:title`,
46	    "--json", "number,body,state",
47	  );
48	  if (result.code !== 0) {
49	    log(`WARN could not look for an existing notice in ${repo}: ${result.stderr.trim() || `gh exited ${result.code}`}`);
50	    return null;
51	  }
52	  let parsed: unknown;
53	  try {
54	    parsed = JSON.parse(result.stdout || "[]");
55	  } catch {
56	    log(`WARN the issue search in ${repo} did not answer with JSON`);
57	    return null;
58	  }
59	  if (!Array.isArray(parsed)) {
60	    log(`WARN the issue search in ${repo} did not answer with a list`);
61	    return null;
62	  }
63	  const found = parsed.find((entry) => {
64	    const issue = entry as { number?: unknown; body?: unknown; state?: unknown };
65	    // `state` absent is left to the server's own filter; present and not open is
66	    // not a notice this run may touch.
67	    return (
68	      typeof issue.body === "string" &&
69	      issue.body.includes(NOTICE_MARKER) &&
70	      (issue.state === undefined || issue.state === "OPEN")
71	    );
72	  }) as { number?: unknown } | undefined;
73	  const number = Number(found?.number ?? 0);
74	  return Number.isInteger(number) && number > 0 ? number : 0;
75	}
